#different agrregations
weekly &lt;- JTOPI_ret |&gt;
  index_by(week = yearweek(Date)) |&gt;
  summarise(ret = sum(J200.JO.Adjusted, na.rm = TRUE))

monthly &lt;- JTOPI_ret |&gt;
  index_by(month = yearmonth(Date)) |&gt;
  summarise(ret = sum(J200.JO.Adjusted, na.rm = TRUE))

quarterly &lt;- JTOPI_ret |&gt;
  index_by(quarter = yearquarter(Date)) |&gt;
  summarise(ret = sum(J200.JO.Adjusted, na.rm = TRUE))

yearly &lt;- JTOPI_ret |&gt;
  index_by(year = year(Date)) |&gt;
  summarise(ret = sum(J200.JO.Adjusted, na.rm = TRUE))




